Scan rows from 5 downward in Sheet1 and treat each contiguous non-empty block in A:X as one group. For each group, compare column K values, marking Y for the maximum (all ties) and N otherwise, with single-row groups as Y. Write the resulting Y/N values into Z5:Z43, leaving non-data rows empty.

```python
import shutil
import openpyxl
import math

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

SHEET = "Sheet1"
if SHEET not in wb.sheetnames:
    wb.create_sheet(SHEET)
ws = wb[SHEET]

if SHEET not in vals.sheetnames:
    vws = vals.create_sheet(SHEET)
else:
    vws = vals[SHEET]

START_ROW = 5
ANSWER_END_ROW = 43
LAST_DATA_COL = 24  # X
K_COL = 11          # K
Z_COL = 26          # Z

def has_data(row):
    for col in range(1, LAST_DATA_COL + 1):
        v = vws.cell(row=row, column=col).value
        if v is None:
            continue
        if isinstance(v, str) and not v.strip():
            continue
        return True
    return False

def get_k(row):
    v = vws.cell(row=row, column=K_COL).value
    if v is None:
        return None
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).strip().replace(",", ""))
    except Exception:
        return None

last_row = max(vws.max_row or 0, ANSWER_END_ROW)

groups = []
r = START_ROW
while r <= last_row:
    if has_data(r):
        r2 = r
        while r2 + 1 <= last_row and has_data(r2 + 1):
            r2 += 1
        groups.append((r, r2))
        r = r2 + 1
    else:
        r += 1

# Ensure the answer region starts clean.
for r in range(START_ROW, ANSWER_END_ROW + 1):
    ws.cell(row=r, column=Z_COL).value = None

for r1, r2 in groups:
    size = r2 - r1 + 1
    k_values = [get_k(r) for r in range(r1, r2 + 1)]
    valid_values = [x for x in k_values if x is not None]
    max_value = max(valid_values) if valid_values else None

    for i, r in enumerate(range(r1, r2 + 1)):
        if size == 1:
            result = "Y"
        elif max_value is None:
            result = "N"
        else:
            kv = k_values[i]
            result = "Y" if kv is not None and math.isclose(kv, max_value, rel_tol=0.0, abs_tol=1e-9) else "N"

        if START_ROW <= r <= ANSWER_END_ROW:
            ws.cell(row=r, column=Z_COL).value = result

wb.save(OUT)

print("groups:", groups)
print("answers:", [(r, ws.cell(row=r, column=Z_COL).value) for r in range(START_ROW, ANSWER_END_ROW + 1) if ws.cell(row=r, column=Z_COL).value is not None])
```

